import{_ as a}from"./chunks/architecture.Cs8uKTTN.js";import{_ as t,o as r,c as o,a2 as i}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"dev-guide/architecture.md","filePath":"dev-guide/architecture.md","lastUpdated":1785993908000}'),s={name:"dev-guide/architecture.md"};function n(l,e,c,d,h,p){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p><img src="'+a+'" alt="Lertaro architecture"></p><h2 id="process-split" tabindex="-1">Process split <a class="header-anchor" href="#process-split" aria-label="Permalink to &quot;Process split&quot;">​</a></h2><p>Lertaro runs as three separate processes, deliberately isolated by privilege level and lifetime:</p><ul><li><strong><code>Lertaro.Service</code></strong> — a Windows service running as <code>LocalSystem</code>. It owns all file indexing: reading the USN Journal and MFT for NTFS/ReFS drives, walking and watching other local file systems directly (they have no journal to read), scanning and caching network shares, and answering search queries over a named pipe. Running this at SYSTEM level means it can read the raw volume metadata every user account is allowed to see, without granting the interactive App process elevated privileges it doesn&#39;t need.</li><li><strong><code>Lertaro.App</code></strong> — the per-user, session-level WPF application: the search windows, the Settings window, hotkey handling, and the Actions/QuickLook UI. It talks to the Service over a named pipe (<code>SearchService</code>/<code>UsnServicePipeServer</code> in <code>Core.Services</code>) and never touches the disk index directly. It also hosts a second, per-user pipe of its own (<code>AppSearchPipeService</code>) that lets the <code>lff</code> CLI companion (see <a href="./../user-guide/cli.html">Command-Line Search</a>) reuse the App&#39;s already-initialized search state — loaded alias/plugin providers, configured network-drive indexes — instead of a bare client process having to replicate that setup itself.</li><li><strong><code>Lertaro.Service --hook</code></strong> — a small separate process hosting the low-level global keyboard hook, so a hook crash or a misbehaving foreground app can&#39;t take the main App process down with it. It also loads plugins&#39; window-integration adapters and runs their calls itself — see <a href="#where-plugins-fit">Where plugins fit</a> below.</li></ul><h2 id="shared-core" tabindex="-1">Shared Core <a class="header-anchor" href="#shared-core" aria-label="Permalink to &quot;Shared Core&quot;">​</a></h2><p><code>Core</code> is a class library referenced by both the Service and the App. It holds:</p><ul><li>The search engine (<code>Core/SearchIndex/Fzf/*</code>) — a fuzzy-matching implementation modeled on the <code>fzf</code> command-line tool&#39;s algorithm, plus a query parser (<code>SearchQueryParser</code>) for drive-letter targeting and path-mode search.</li><li>The runtime index (<code>Core/IndexV2/*</code>) — a memory-mapped, columnar snapshot format built from USN/MFT reads, with an in-memory delta overlay for changes since the last snapshot.</li><li>IPC contracts (<code>SearchRequestMessage</code>, <code>SearchResponseBinarySerializer</code>, ...) shared verbatim by both processes, so the App and Service always agree on the wire format.</li><li><code>Logger</code> — writes to per-process log files (<code>service.log</code>, <code>app.log</code>, <code>hook.log</code>), all readable (but not all writable) from the App&#39;s Settings → Service Status log viewer.</li></ul><h2 id="where-plugins-fit" tabindex="-1">Where plugins fit <a class="header-anchor" href="#where-plugins-fit" aria-label="Permalink to &quot;Where plugins fit&quot;">​</a></h2><p>Plugins are <code>.dll</code> assemblies referencing <code>PluginSdk</code> and are loaded by the App process (see <a href="./getting-started.html">Getting Started</a> and <a href="./packaging.html">Packaging &amp; Deployment</a>). Two plugins ship with Lertaro itself as first-class examples — <code>Lertaro.Plugins.CoreExtensions</code> (built-in file actions and the shell context-menu integration) and <code>Lertaro.Plugins.PinyinAlias</code> (pinyin aliasing for Chinese filenames) — see <a href="./examples.html">Example Plugins</a> for a walkthrough of both.</p><p>Plugins never talk to the Service directly; they interact with the App through the interfaces documented in the Plugin SDK Reference, and with the disk index (when they need custom indexed directories) through <code>DirectoryIndexerService</code>, which proxies to the Service on their behalf.</p><p>Window-integration adapters are the one exception to being App-only: <a href="./sdk/system-adapters.html"><code>IActivePathCollector</code>, <code>IFileDialogAdapter</code>, and <code>IInlineSearchAdapter</code></a> implementations are loaded a second time into the Hook process, and their calls run there instead of in the App. This is what lets Lertaro drive an elevated File Explorer/file dialog/third-party file manager window even though the App itself always runs unelevated — Windows blocks a lower-privilege process from sending input to a higher-privilege one, so the call has to originate from a process running at the same privilege level as the target.</p>',12)])])}const f=t(s,[["render",n]]);export{m as __pageData,f as default};
